from pathlib import Path
p=Path('src/views/CentroSoporte.vue');s=p.read_text(encoding='utf-8')
s=s.replace('<button v-if="staff && !detail.ticket.technician_id" class="support-primary" :disabled="saving" @click="accept">Aceptar y atender ticket</button>', '<form v-if="staff && !detail.ticket.technician_id" class="support-accept-form" @submit.prevent="accept"><label>Tiempo estimado (minutos)<input type="number" v-model.number="acceptMinutes" min="1" max="43200" required placeholder="Ej. 30"></label><button class="support-primary" :disabled="saving">Aceptar y atender ticket</button></form>')
s=s.replace('<p>Solicitante: {{detail.ticket.requester_name || detail.ticket.requester_id}}</p>', '''<section class="support-estimate-strip"><strong>Solución estimada: {{detail.ticket.expected_resolution_at?date(detail.ticket.expected_resolution_at):'El técnico debe confirmarla'}}</strong><span v-if="detail.ticket.estimated_minutes">{{detail.ticket.estimated_minutes}} min desde la última estimación · Horario de Lima</span><small>Es una estimación. Cualquier cambio queda registrado en el seguimiento.</small></section><p>Solicitante: {{detail.ticket.requester_name || detail.ticket.requester_id}}</p>''')
s=s.replace('<h3>Conversación</h3>', '''<details v-if="canManage && ['assigned','in_progress','waiting_customer','escalated'].includes(detail.ticket.status)" class="support-estimate-editor"><summary>Actualizar tiempo estimado</summary><form class="support-form support-form-grid" @submit.prevent="updateEstimate"><label>Minutos desde ahora<input type="number" v-model.number="estimate.minutes" required min="1" max="43200"></label><label>Explicación para el cliente<input v-model="estimate.reason" required maxlength="10000" placeholder="Explica el avance y el motivo del nuevo plazo"></label><button :disabled="saving">Actualizar e informar al cliente</button></form></details><h3>Conversación</h3>''')
s=s.replace("technician:'',change:","technician:'',acceptMinutes:'',estimate:{minutes:'',reason:''},change:")
s=s.replace("technician:this.context.principal}","technician:this.context.principal,estimated_minutes:this.acceptMinutes}")
s=s.replace("this.technician=this.detail.ticket.technician_id||'';","this.technician=this.detail.ticket.technician_id||'';this.acceptMinutes='';this.estimate={minutes:'',reason:''};")
s=s.replace('async assign(){',"async updateEstimate(){if(await this.act('transition',{id:this.detail.ticket.id,version:this.detail.ticket.version,status:this.detail.ticket.status,reason:this.estimate.reason,estimated_minutes:this.estimate.minutes})){this.estimate={minutes:'',reason:''};await this.refreshDetail();await this.loadTickets()}},async assign(){")
p.write_text(s,encoding='utf-8')
